const acquired = acquirePrivateFoodMenuDatabaseFromEnvironment({ environment, bindingName: "RIVER_FOOD_DB" });
if (!acquired.ok) return configurationFailure();
const repository = new D1FoodDraftRepository(acquired.value);
const readDependencies = createFoodMenuReadDependencies({ repository });
const runtime = createPrivateFoodMenuOperationRuntimeFromServerContext({ environment, bindingName: "RIVER_FOOD_DB", session: context.session, readDependencies, administratorPrincipalId });
if (!runtime.ok) return configurationFailure();
const boundary = createPrivateFoodMenuMutationRequestBoundary({ operationGate: runtime.value.operationGate, workspace: runtime.value.workspace, expectedOrigin });
const adapter = createPrivateFoodMenuMutationRequestAdapter({ boundary });
const handler = createPrivateFoodMenuMutationServerHandler({ adapter });
return handler.handle(context.request);
